  const query = { b: 1, c: 3, a: 2 };
  const base = { baseUrl: 'https://api.example.test', path: ['items'], query };

  assert.equal(buildUrl(base), 'https://api.example.test/items?a=2&b=1&c=3');
  assert.equal(
    buildUrl({ ...base, queryOrder: 'sorted' }),
    'https://api.example.test/items?a=2&b=1&c=3'
  );
});

test('buildUrl keeps query object order with queryOrder "insertion"', () => {
  const url = buildUrl({
    baseUrl: 'https://api.example.test',
    path: ['items'],
    query: { b: 1, c: 3, a: 2 },
    queryOrder: 'insertion'
  });

  assert.equal(url, 'https://api.example.test/items?b=1&c=3&a=2');
});

test('buildUrl keeps array items in array order under both query orders', () => {
  const query = { z: ['3', '1', '2'], a: 'x' };
  const base = { baseUrl: 'https://api.example.test', query };

  assert.equal(buildUrl(base), 'https://api.example.test/?a=x&z=3&z=1&z=2');
  assert.equal(
    buildUrl({ ...base, queryOrder: 'insertion' }),
    'https://api.example.test/?z=3&z=1&z=2&a=x'
  );
});

test('buildUrl throws TypeError for an unknown queryOrder', () => {
  for (const queryOrder of ['reverse', 'SORTED', '', null, 1, true]) {
    assert.throws(
      () => buildUrl({ baseUrl: 'https://api.example.test', query: { a: 1 }, queryOrder }),
      TypeError,
      `queryOrder ${String(queryOrder)}`
    );
  }
});

test('buildUrl passes a URLSearchParams query through unchanged for both query orders', () => {
  const query = new URLSearchParams([['b', '1'], ['a', '2']]);
  for (const queryOrder of [undefined, 'sorted', 'insertion']) {
    assert.equal(
      buildUrl({ baseUrl: 'https://api.example.test', query, queryOrder }),
      'https://api.example.test/?b=1&a=2'
    );
  }
});

test('buildSignedUrl forwards queryOrder to buildUrl', () => {
  const options = {
    baseUrl: 'https://api.example.test',
    path: ['items'],
    query: { b: 1, a: 2 },
    queryOrder: 'insertion'
  };
  const signed = buildSignedUrl(options, 'secret');

  assert.ok(signed.startsWith('https://api.example.test/items?b=1&a=2&signature='));
  assert.throws(() => buildSignedUrl({ ...options, queryOrder: 'nope' }, 'secret'), TypeError);
});
